INSERT INTO `competitions` VALUES ('17b95192-d13a-42ab-9520-0f875fab5e9c',NULL,'TMC OYO STATE ANNUAL QURAN COMPETITION','2026 EDITION OF ANNUAL QURAN COMPETITION. FINAL 10AM - JUNE 20, 2026. The categories (WHOLE QURAN,ONE THIRD OF THE QURAN,ONE SIXTH OF THE QURAN)',2026,'2026-03-23 00:00:00.000','2026-05-23 00:00:00.000','ACTIVE','[{\"id\": \"fullName\", \"type\": \"text\", \"label\": \"Full Name (Surname first)\", \"required\": true, \"placeholder\": \"e.g. Mustapha Ahmad Ibrahim\"}, {\"id\": \"email\", \"type\": \"email\", \"label\": \"Email Address\", \"required\": true, \"placeholder\": \"applicant@email.com\"}, {\"id\": \"phone\", \"type\": \"tel\", \"label\": \"Phone Number\", \"required\": true, \"placeholder\": \"08012345678\"}, {\"id\": \"gender\", \"type\": \"select\", \"label\": \"Gender\", \"options\": [\"Male\"], \"required\": true}, {\"id\": \"dateOfBirth\", \"type\": \"date\", \"label\": \"Date of Birth\", \"required\": true}, {\"id\": \"age\", \"type\": \"number\", \"label\": \"Age\", \"required\": true, \"placeholder\": \"e.g. 15\"}, {\"id\": \"parentName\", \"type\": \"text\", \"label\": \"Parent/Guardian Name\", \"required\": true, \"placeholder\": \"Full name of parent/guardian\"}, {\"id\": \"parentPhone\", \"type\": \"tel\", \"label\": \"Parent/Guardian Phone\", \"required\": true, \"placeholder\": \"08012345678\"}, {\"id\": \"zone\", \"type\": \"email\", \"label\": \"Parent/Guardian email\", \"options\": [\"Abeokuta\", \"Ijebu-Ode\", \"Sagamu\", \"Ilaro\"], \"required\": true}, {\"id\": \"field_1774249446702\", \"type\": \"select\", \"label\": \"Categories\", \"options\": [\"WHOLE QURAN\", \"ONE THIRD OF THE QURAN\", \"ONE SIXTH OF THE QURAN\"], \"required\": true, \"placeholder\": \"\"}]','2026-03-23 07:07:15.362','2026-03-23 07:07:15.360'),('efd46f15-a08b-4d6c-8e8b-c6cc84e8fb7d',NULL,'TMC Oyo State Annual Spelling Bee Competition 2026','Annual Spelling Bee Competition for students in Senior Secondary Schools within Oyo State. Open to SS1 and SS2 students.',2026,'2026-03-10 00:00:00.000','2026-04-10 00:00:00.000','ACTIVE','[{\"id\": \"fullName\", \"type\": \"text\", \"label\": \"Full Name (Surname first)\", \"required\": true, \"placeholder\": \"e.g. Mustapha Ahmad Ibrahim\"}, {\"id\": \"email\", \"type\": \"email\", \"label\": \"Email Address\", \"required\": true, \"placeholder\": \"applicant@email.com\"}, {\"id\": \"phone\", \"type\": \"tel\", \"label\": \"Phone Number\", \"required\": true, \"placeholder\": \"08012345678\"}, {\"id\": \"gender\", \"type\": \"select\", \"label\": \"Gender\", \"options\": [\"Male\", \"Female\"], \"required\": true}, {\"id\": \"dateOfBirth\", \"type\": \"date\", \"label\": \"Date of Birth\", \"required\": true}, {\"id\": \"age\", \"type\": \"number\", \"label\": \"Age\", \"required\": true, \"placeholder\": \"e.g. 15\"}, {\"id\": \"currentClass\", \"type\": \"select\", \"label\": \"Current Class\", \"options\": [\"SS 1\", \"SS 2\"], \"required\": true}, {\"id\": \"schoolName\", \"type\": \"text\", \"label\": \"Name of School\", \"required\": true, \"placeholder\": \"Enter school name\"}, {\"id\": \"schoolAddress\", \"type\": \"textarea\", \"label\": \"School Address\", \"required\": true, \"placeholder\": \"Include LGA and town\"}, {\"id\": \"parentName\", \"type\": \"text\", \"label\": \"Parent/Guardian Name\", \"required\": true, \"placeholder\": \"Full name of parent/guardian\"}, {\"id\": \"parentPhone\", \"type\": \"tel\", \"label\": \"Parent/Guardian Phone\", \"required\": true, \"placeholder\": \"08012345678\"}]','2026-03-10 08:02:22.512','2026-03-10 08:02:22.511');
