INSERT INTO `programme_feedback_submissions` VALUES ('06ddc2c1-3d53-49be-a0b8-3ba6538d6a8e','c709bdc5-2e56-42cd-aa44-889d6e474dbf','522fb0f8-e100-47e3-875b-29e4fb21ea89','{\"field_1\": \"National Officer\", \"field_2\": \"Physically (On-site)\", \"field_3\": \"3\", \"field_4\": \"Yes\", \"field_5\": \"3\", \"field_6\": \"Yes\", \"field_8\": \"Yes\", \"field_9\": \"4\", \"field_10\": \"Yes\", \"field_11\": \"Yes\", \"field_12\": \"4\", \"field_13\": \"Yes\", \"field_14\": \"4\", \"field_15\": \"Yes\", \"field_16\": \"The need to rejig the Tazkiyatu-n-Nafs programme; The Congress\'s spiritual foundation avenue \", \"field_1777991703502\": \"4\", \"field_1777991885446\": \"The 1st & 3rd Sessions\"}','2026-05-06 13:24:40.960'),('07754517-8600-402c-9f1e-7d896cdcd906','c709bdc5-2e56-42cd-aa44-889d6e474dbf',NULL,'{\"field_1\": \"State Officer\", \"field_2\": \"Virtually (Online)\", \"field_3\": \"4\", \"field_4\": \"Yes\", \"field_7\": \"Yes\", \"field_8\": \"Yes\", \"field_9\": \"5\", \"field_10\": \"Yes\", \"field_11\": \"Yes\", \"field_12\": \"4\", \"field_13\": \"Yes\", \"field_14\": \"4\", \"field_15\": \"Yes\", \"field_16\": \"1. Enough time should be provided for such workshop like complete two days \\n\\n2. Provision for convenience sleeping should be considered \", \"field_1777991703502\": \"5\", \"field_1777991885446\": \"The lecture presented by Alh. Mikhail Animosahun, NADMIN\"}','2026-05-06 17:44:35.453'),('0cc59885-fb66-426b-90f1-803b27192cf6','c709bdc5-2e56-42cd-aa44-889d6e474dbf','1d164621-407f-40c7-b15d-e116c9ee49f8','{\"field_1\": \"State Officer\", \"field_2\": \"Physically (On-site)\", \"field_3\": \"2\", \"field_4\": \"No\", \"field_5\": \"4\", \"field_6\": \"Yes\", \"field_9\": \"5\", \"field_10\": \"Yes\", \"field_11\": \"Yes\", \"field_12\": \"4\", \"field_13\": \"Yes\", \"field_14\": \"3\", \"field_15\": \"Yes\", \"field_16\": \"Going forward, all members should have been given the opportunity of attending it either physically or virtually, especially all those outside Lagos State \"}','2026-05-05 13:50:31.422'),('0d53fc36-a1ce-42d0-bb2c-dc9d84996697','c709bdc5-2e56-42cd-aa44-889d6e474dbf','a9b2cabd-0b28-4394-9d97-968df8a36322','{\"field_1\": \"National Officer\", \"field_2\": \"Physically (On-site)\", \"field_3\": \"4\", \"field_4\": \"Yes\", \"field_5\": \"4\", \"field_6\": \"Yes\", \"field_7\": \"Yes\", \"field_8\": \"Yes\", \"field_9\": \"5\", \"field_10\": \"Yes\", \"field_11\": \"Yes\", \"field_12\": \"5\", \"field_13\": \"Yes\", \"field_14\": \"5\", \"field_15\": \"Yes\", \"field_16\": \"Pre-event registration link to be made available at least a week before the event\"}','2026-05-05 13:07:05.776'),('1258fa59-22b4-4c65-8b6c-3e0d37b2e359','c709bdc5-2e56-42cd-aa44-889d6e474dbf',NULL,'{\"field_1\": \"State Officer\", \"field_2\": \"Physically (On-site)\", \"field_3\": \"2\", \"field_4\": \"No\", \"field_5\": \"1\", \"field_6\": \"Yes\", \"field_7\": \"Yes\", \"field_8\": \"Yes\", \"field_9\": \"3\", \"field_10\": \"Yes\", \"field_11\": \"Yes\", \"field_12\": \"2\", \"field_13\": \"No\", \"field_14\": \"3\", \"field_15\": \"Yes\", \"field_16\": \"Is very educative and understood, encouragable one.\", \"field_1777991703502\": \"3\", \"field_1777991885446\": \"Quaterly\"}','2026-05-06 02:28:53.966'),('12dbb438-e3f1-46ac-9bd5-ee2cd029fc47','c709bdc5-2e56-42cd-aa44-889d6e474dbf',NULL,'{\"field_1\": \"State Officer\", \"field_2\": \"Physically (On-site)\", \"field_3\": \"4\", \"field_4\": \"Yes\", \"field_5\": \"5\", \"field_6\": \"Yes\", \"field_7\": \"Yes\", \"field_8\": \"Yes\", \"field_9\": \"5\", \"field_10\": \"Yes\", \"field_11\": \"Yes\", \"field_13\": \"Yes\", \"field_14\": \"4\", \"field_15\": \"Yes\", \"field_16\": \"There is need to improve on environmental sanitation/fumigation as mosquito bite was serious challenge.\\nThe program started lately on Friday and led to inability to finish earlier. As a result those that came from far left lately for their various destination.\", \"field_1777991703502\": \"5\", \"field_1777991885446\": \"The first lecture by Ustaz Ariremako.\"}','2026-05-06 12:49:14.050'),('13c06b7d-1468-4050-8750-afd31fba2a59','c709bdc5-2e56-42cd-aa44-889d6e474dbf',NULL,'{\"field_1\": \"Local Government Officer\", \"field_2\": \"Physically (On-site)\", \"field_3\": \"3\", \"field_4\": \"Yes\", \"field_5\": \"5\", \"field_6\": \"Yes\", \"field_7\": \"No\", \"field_8\": \"Yes\", \"field_9\": \"4\", \"field_10\": \"Yes\", \"field_11\": \"Yes\", \"field_12\": \"4\", \"field_13\": \"Yes\", \"field_14\": \"4\", \"field_15\": \"Yes\", \"field_16\": \"We should always encourage our officers in each level to participate.\\nAll lectures taught should be put into practice so as to have impact in our society.\", \"field_1777991703502\": \"4\", \"field_1777991885446\": \"Shifting from old system to digital level.Also the taxes as part of current issues.\"}','2026-05-06 07:31:29.374'),('197525fb-bf94-4459-9746-de69e5686955','c709bdc5-2e56-42cd-aa44-889d6e474dbf',NULL,'{\"field_1\": \"State Officer\", \"field_2\": \"Physically (On-site)\", \"field_3\": \"5\", \"field_4\": \"Yes\", \"field_5\": \"5\", \"field_6\": \"Yes\", \"field_8\": \"Yes\", \"field_9\": \"5\", \"field_10\": \"Yes\", \"field_11\": \"Yes\", \"field_12\": \"5\", \"field_13\": \"Yes\", \"field_14\": \"5\", \"field_16\": \"The ICT should improve on the live streaming of our programs \", \"field_1777991703502\": \"5\", \"field_1777991885446\": \"The first Session.\"}','2026-05-06 18:34:26.886'),('1b113a11-e49e-4418-97a3-487febd09c83','c709bdc5-2e56-42cd-aa44-889d6e474dbf','1b3aa489-a4bf-4280-abb0-98a5656cc086','{\"field_1\": \"National Officer\", \"field_2\": \"Physically (On-site)\", \"field_3\": \"5\", \"field_4\": \"Yes\", \"field_5\": \"5\", \"field_6\": \"Yes\", \"field_7\": \"Yes\", \"field_8\": \"Yes\", \"field_9\": \"4\", \"field_11\": \"Yes\", \"field_12\": \"4\", \"field_13\": \"Yes\", \"field_14\": \"4\", \"field_15\": \"Yes\", \"field_16\": \"Let\'s try to implement and all what we we