DROP TABLE IF EXISTS `programme_reports`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `programme_reports` (
  `id` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `programmeId` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `summary` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `challenges` text COLLATE utf8mb4_unicode_ci,
  `comments` text COLLATE utf8mb4_unicode_ci,
  `attendeesMale` int NOT NULL DEFAULT '0',
  `attendeesFemale` int NOT NULL DEFAULT '0',
  `amountSpent` decimal(15,2) DEFAULT '0.00',
  `images` json DEFAULT NULL,
  `submittedBy` varchar(191) COLLATE utf8mb4_unicode_ci NOT NULL,
  `submittedAt` datetime(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `startTime` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `endTime` varchar(255) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `lecturers` text COLLATE utf8mb4_unicode_ci,
  `topic` text COLLATE utf8mb4_unicode_ci,
  PRIMARY KEY (`id`),
  UNIQUE KEY `programme_reports_programmeId_key` (`programmeId`),
  KEY `programme_reports_submittedBy_fkey` (`submittedBy`),
  CONSTRAINT `programme_reports_programmeId_fkey` FOREIGN KEY (`programmeId`) REFERENCES `programmes` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `programme_reports_submittedBy_fkey` FOREIGN KEY (`submittedBy`) REFERENCES `users` (`id`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
